use super::*;use crate::key_policy_control::{Control,Controlled};use std::io;
struct Work{left:usize,polls:usize,fail_at:usize}
impl Control for Work{type Error=io::Error;const CHECKED:bool=true;fn checkpoint(&mut self)->Result<(),Self::Error>{self.polls+=1;if self.polls==self.fail_at{Err(io::Error::from_raw_os_error(1450))}else{Ok(())}}fn reserve(&mut self,n:usize)->Result<(),Self::Error>{self.checkpoint()?;self.left=self.left.checked_sub(n).ok_or_else(||io::Error::from(io::ErrorKind::OutOfMemory))?;Ok(())}fn overflow(&mut self)->Self::Error{io::ErrorKind::OutOfMemory.into()}fn allocation_failed(&mut self)->Self::Error{io::ErrorKind::OutOfMemory.into()}}
#[test]fn actual_nested_argument_and_marker_first_io_is_durable_then_fresh_work_recovers(){let text="make(/obj/item, value = foo(bar(1), list(2, 3)))";for fail_at in [2,7,17,31]{let gate=Controlled::new(Work{left:1<<20,polls:0,fail_at});let rows=calls_using(text,&gate);assert!(!gate.checkpoint());assert_eq!(gate.finish(rows).unwrap_err().raw_os_error(),Some(1450));}let gate=Controlled::new(Work{left:1<<20,polls:0,fail_at:usize::MAX});let rows=calls_using(text,&gate);assert_eq!(gate.finish(rows).unwrap(),calls(text));let gate=Controlled::new(Work{left:0,polls:0,fail_at:usize::MAX});let rows=calls_using(text,&gate);assert_eq!(gate.finish(rows).unwrap_err().kind(),io::ErrorKind::OutOfMemory);}
#[test]fn actual_raw_positions_and_per_type_ordinal_contract_is_preserved(){let mut d=Declared::default();d.marker("/obj/parent",&["/obj/parent".into(),"param(nameof(value), pos = 1)".into()],"code/a.dm",2);d.marker("/obj/parent/child",&["/obj/parent/child".into(),"param(nameof(other), pos = 1)".into()],"code/b.dm",3);let mut found=Vec::new();position_findings(&d,&|_|false,&mut|r,p,l,m|found.push((r,p.to_owned(),l,m)));assert_eq!(found.len(),1);assert_eq!(found[0].0,"param_pos_override");assert_eq!(Declared::lineage("/obj/parent/child"),vec!["/obj/parent/child","/obj/parent","/obj"]);let gate=Controlled::new(Work{left:1<<20,polls:0,fail_at:usize::MAX});let mut controlled=Vec::new();position_findings_using(&d,&|_|false,&mut|r,p,l,m|controlled.push((r,p.to_owned(),l,m)),&gate);gate.finish(()).unwrap();assert_eq!(controlled,found);}
